58	    /**
59	     * Pattern for a syntactically valid email address: a non-empty local part, an '@', and a
60	     * dotted domain ending in a letters-only label. Applied to the trimmed, lower-cased value.
61	     */
62	    private static final Pattern EMAIL_PATTERN =
63	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
