108	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
109	    @Override
110	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
111	        HttpHeaders headers = new HttpHeaders();
112	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
113	        String telephone = normalizeTelephone(owner.getTelephone());
114	        if (telephone.length() != 10) {
115	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
116	        }
117	        owner.setTelephone(telephone);
118	        if (owner.getEmail() != null) {
119	            String email = normalizeEmail(owner.getEmail());
120	            if (!EMAIL_PATTERN.matcher(email).matches()) {
121	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
122	            }
123	            owner.setEmail(email);
124	        }
125	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
126	            .anyMatch(existing -> telephone.equals(normalizeTelephone(existing.getTelephone())));
127	        if (telephoneInUse) {
128	            return new ResponseEntity<>(HttpStatus.CONFLICT);
129	        }
130	        this.clinicService.saveOwner(owner);
131	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
132	        headers.setLocation(UriComponentsBuilder.newInstance()
133	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
